<script setup>
import { computed, ref } from 'vue'
import { useRouter } from 'vue-router'
import { useEvents } from '@/composables/useEvents'
import AppModal from '@/components/ui/AppModal.vue'
const router=useRouter(),{userRegistrations,getEventById,isEventDone,cancelRegistration}=useEvents()
const selected=ref(null), modal=ref(false)
const tickets=computed(()=>userRegistrations.value.map(registration=>({registration,event:getEventById(registration.eventId)})).filter(item=>item.event).sort((a,b)=>new Date(a.event.date)-new Date(b.event.date)))
const upcoming=computed(()=>tickets.value.filter(t=>!isEventDone(t.event.id))), concluded=computed(()=>tickets.value.filter(t=>isEventDone(t.event.id)))
function confirmCancel(){if(selected.value)cancelRegistration(selected.value.id);selected.value=null;modal.value=false}
function date(v){if(!v)return 'Date to be announced';const d=new Date(v);return Number.isNaN(d.getTime())?v:new Intl.DateTimeFormat('en',{dateStyle:'medium',timeStyle:'short'}).format(d)}
</script>
<template><main class="your-events"><header class="heading"><div><span class="eyebrow">YOUR GATHERINGS</span><h1>Your Events</h1><p>Keep your tickets close and manage your upcoming plans.</p></div><RouterLink to="/browse/events" class="browse">Explore events ↗</RouterLink></header><section v-if="!tickets.length" class="empty"><span class="empty-icon">✦</span><h2>Your next experience starts here</h2><p>When you register for an event, your tickets and event details will appear on this page.</p><RouterLink to="/browse/events" class="browse">Find an event</RouterLink></section><template v-else><section v-if="upcoming.length" class="ticket-section"><h2>Upcoming <span>{{upcoming.length}}</span></h2><div class="ticket-grid"><article v-for="item in upcoming" :key="item.registration.id" class="ticket-card"><div class="ticket-art">{{item.event.category?.slice(0,1)||'G'}}<span>{{item.event.category}}</span></div><div class="ticket-content"><div class="ticket-top"><span class="status upcoming">Upcoming</span><span class="ref">{{item.registration.reference}}</span></div><h3>{{item.event.title}}</h3><p>{{date(item.event.date)}} · {{item.event.location}}</p><div class="ticket-actions"><button @click="router.push(`/your-events/${item.registration.id}`)">View ticket →</button><button class="cancel" @click="selected=item.registration;modal=true">Cancel registration</button></div></div></article></div></section><section v-if="concluded.length" class="ticket-section"><h2>Past events <span>{{concluded.length}}</span></h2><div class="ticket-grid"><article v-for="item in concluded" :key="item.registration.id" class="ticket-card"><div class="ticket-art archived">✓<span>{{item.event.category}}</span></div><div class="ticket-content"><div class="ticket-top"><span class="status archived-label">Archived</span><span class="ref">{{item.registration.reference}}</span></div><h3>{{item.event.title}}</h3><p>{{date(item.event.date)}} · {{item.event.location}}</p><div class="ticket-actions"><button @click="router.push(`/your-events/${item.registration.id}`)">View receipt →</button></div></div></article></div></section></template><AppModal :isopen="modal" title="Cancel this registration?" :message="`Your spot for ${selected ? getEventById(selected.eventId)?.title : 'this event'} will be released.`" confirm-text="Cancel registration" @confirm="confirmCancel" @close="modal=false"/></main></template>
<style scoped>.your-events{max-width:1100px;margin:auto;color:#211d47}.heading{display:flex;align-items:flex-end;justify-content:space-between;gap:1rem;margin-bottom:2rem}.eyebrow{color:#9997aa;font-size:.65rem;font-weight:800;letter-spacing:.15em}.heading h1{margin:.35rem 0;font-size:clamp(1.8rem,4vw,2.45rem);letter-spacing:-.04em}.heading p{margin:0;color:#858397;font-size:.87rem}.browse{display:inline-flex;padding:.75rem .95rem;border-radius:11px;color:white;background:#6748ed;text-decoration:none;font-size:.78rem;font-weight:750;white-space:nowrap}.ticket-section{margin:1.6rem 0 2.3rem}.ticket-section>h2{display:flex;align-items:center;gap:.6rem;margin-bottom:1rem;font-size:1.05rem}.ticket-section>h2 span{display:grid;place-items:center;min-width:24px;height:24px;padding:0 .3rem;border-radius:99px;color:#6748ed;background:#f0edff;font-size:.7rem}.ticket-grid{display:grid;grid-template-columns:repeat(auto-fill,minmax(min(100%,400px),1fr));gap:1rem}.ticket-card{overflow:hidden;border:1px solid #eeedf4;border-radius:17px;background:#fff;box-shadow:0 8px 28px #251d4709}.ticket-art{position:relative;display:grid;place-items:center;height:90px;color:white;background:linear-gradient(120deg,#8872ef,#ddb2dc 65%,#ffd3b0);font-size:1.8rem;font-weight:800}.ticket-art span{position:absolute;left:.8rem;bottom:.65rem;padding:.25rem .5rem;border-radius:99px;color:#513ca3;background:#ffffffd1;font-size:.63rem;font-weight:750}.ticket-art.archived{background:linear-gradient(120deg,#8da99b,#c7d7cf)}.ticket-content{padding:1rem}.ticket-top{display:flex;justify-content:space-between;align-items:center;gap:.5rem}.status{padding:.28rem .5rem;border-radius:99px;font-size:.63rem;font-weight:800}.upcoming{color:#17734f;background:#eaf8f0}.archived-label{color:#77768a;background:#f0f0f4}.ref{color:#9291a3;font-size:.63rem}.ticket-content h3{margin:.65rem 0 .3rem;font-size:1rem}.ticket-content p{margin:0;color:#858397;font-size:.74rem;line-height:1.5}.ticket-actions{display:flex;gap:.5rem;margin-top:1rem;padding-top:.8rem;border-top:1px solid #f0eff5}.ticket-actions button{padding:.55rem .7rem;border:0;border-radius:9px;color:#6748ed;background:#f0edff;font:inherit;font-size:.7rem;font-weight:750;cursor:pointer}.ticket-actions button.cancel{color:#b83b54;background:#fff0f2}.empty{display:grid;justify-items:center;padding:4rem 1rem;border:1px solid #eeedf4;border-radius:18px;background:#fff;text-align:center}.empty-icon{display:grid;place-items:center;width:62px;height:62px;border-radius:20px;color:#6748ed;background:#f0edff;font-size:1.7rem}.empty h2{margin:1rem 0 .4rem;font-size:1.15rem}.empty p{max-width:420px;margin:0 0 1rem;color:#858397;font-size:.8rem;line-height:1.6}@media(max-width:600px){.heading{align-items:flex-start;flex-direction:column}.ticket-actions{flex-wrap:wrap}}</style>
